import{_ as l,o as i,c as e,a2 as t}from"./chunks/framework.BbQrW5_t.js";const _=JSON.parse('{"title":"高级篇·专精","description":"","frontmatter":{"title":"高级篇·专精","date":"2026-09-03T00:00:00.000Z"},"headers":[],"relativePath":"study/cyber-security/03-高级篇-专精.md","filePath":"study/cyber-security/03-高级篇-专精.md","lastUpdated":null}'),r={name:"study/cyber-security/03-高级篇-专精.md"};function o(u,a,n,d,s,c){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="🎯-高级篇-·-专精-第-3-年" tabindex="-1">🎯 高级篇 · 专精（第 3 年） <a class="header-anchor" href="#🎯-高级篇-·-专精-第-3-年" aria-label="Permalink to &quot;🎯 高级篇 · 专精（第 3 年）&quot;">​</a></h1><blockquote><p>目标：方向分化定终身，OSCP 或对等高阶认证，攻防任务从&quot;参与&quot;到&quot;有角色&quot;。</p></blockquote><h2 id="方向-a-红队-进攻的艺术" tabindex="-1">方向 A：红队（进攻的艺术） <a class="header-anchor" href="#方向-a-红队-进攻的艺术" aria-label="Permalink to &quot;方向 A：红队（进攻的艺术）&quot;">​</a></h2><ul><li>免杀与对抗概念：EDR 如何看世界、加载器思路（<strong>靶场自用环境</strong>）</li><li>C2 框架深入（Sliver/Cobalt Strike 认知级）</li><li>初始访问组合拳：钓鱼仿真、边界资产 pinpoint</li><li>对应认证：OSCP → CRTO 路线</li></ul><h2 id="方向-b-漏洞研究-深度挖掘" tabindex="-1">方向 B：漏洞研究（深度挖掘） <a class="header-anchor" href="#方向-b-漏洞研究-深度挖掘" aria-label="Permalink to &quot;方向 B：漏洞研究（深度挖掘）&quot;">​</a></h2><ul><li>CVE 复现工程化：建自己的 CVE 复现库（每篇复现=一篇博客）</li><li>Fuzzing 入门：AFL/libFuzzer 对文件解析器做突变</li><li>1-day 挖掘：补丁 diff 分析（你有 diff 阅读天赋）</li><li>目标产出：1 个 CVE 编号或 1 篇高质量漏洞分析</li></ul><h2 id="方向-c-蓝队体系-防守纵深" tabindex="-1">方向 C：蓝队体系（防守纵深） <a class="header-anchor" href="#方向-c-蓝队体系-防守纵深" aria-label="Permalink to &quot;方向 C：蓝队体系（防守纵深）&quot;">​</a></h2><ul><li>检测规则工程：Sigma 规则编写、ATT&amp;CK 映射</li><li>蜜罐与欺骗防御、威胁情报落地</li><li>对应认证：CISP-IRE → GCFA 路线</li></ul><h2 id="通用模块-云与-ai-安全-未来五年门票" tabindex="-1">通用模块：云与 AI 安全（未来五年门票） <a class="header-anchor" href="#通用模块-云与-ai-安全-未来五年门票" aria-label="Permalink to &quot;通用模块：云与 AI 安全（未来五年门票）&quot;">​</a></h2><ul><li>云安全基础：IAM 错配/对象存储越权/元数据 SSRF（各大厂 CTF 常客）</li><li>AI 安全初探：Prompt 注入、模型供应链——你的 AI 工作流优势区</li></ul><h2 id="🎓-特色收官-教学融合项目" tabindex="-1">🎓 特色收官：教学融合项目 <a class="header-anchor" href="#🎓-特色收官-教学融合项目" aria-label="Permalink to &quot;🎓 特色收官：教学融合项目&quot;">​</a></h2><p>把你两年的攻防笔记改造成**「网络安全与编程思维」青少年选修课教案**（8 课时）：</p><ul><li>密码学游戏 → SQL 注入沙盘 → 社会工程学情景剧</li><li>这是&quot;科技数学教师&quot;简历上独一无二的差异化章节：懂攻防的老师，全国稀缺</li></ul><h2 id="✅-年度验收标准" tabindex="-1">✅ 年度验收标准 <a class="header-anchor" href="#✅-年度验收标准" aria-label="Permalink to &quot;✅ 年度验收标准&quot;">​</a></h2><ul><li>[ ] 主方向认证到手（OSCP / CISP 高阶其一）</li><li>[ ] HTB Pro Lab 或 AD 靶场全线打穿</li><li>[ ] 护网正式角色（红队队员/蓝队分析岗）</li><li>[ ] 教学融合教案 8 课时完稿并试讲</li></ul>',15)])])}const b=l(r,[["render",o]]);export{_ as __pageData,b as default};
